    static long inv=0;
    static int[] mergeSort(int[] a,int l,int r){
        if(l>=r)return new int[]{a[l]};
        int m=(l+r)/2;
        int[] L=mergeSort(a,l,m),R=mergeSort(a,m+1,r);
        int[] merged=new int[L.length+R.length];
        int i=0,j=0,k=0;
        while(i<L.length&&j<R.length){
            if(L[i]<=R[j])merged[k++]=L[i++];
            else{merged[k++]=R[j++];inv+=L.length-i;}
        }
        while(i<L.length)merged[k++]=L[i++];
        while(j<R.length)merged[k++]=R[j++];
        return merged;
    }
